effect.script:
function animate(env,el,p) {
    let groups = [];
    groups.push(0);
    el.shaderGroups = groups;
    return el;
}

effect.shader:
 //////////////////////////
 vec4 newLayer( vec4 a, vec4 b) { return a * (1. - b.a) + b;  }
 mat2 rot2m(float a){ float s = sin(a); float c = cos(a); return mat2(c, -s, s, c); }
 vec2 l2s( vec2 v ) { return (vec4(v,0.0,1.0)*acLayerToScreen).xy; }
 #define fragCoord gl_FragCoord.xy

/////////////////////////

     vec3 rotx(vec3 p, float a){
         float s = sin(a), c = cos(a);
         return vec3(p.x, c*p.y - s*p.z, s*p.y + c*p.z);
     }


     //From Dave_Hoskins (https://www.shadertoy.com/view/4djSRW)
     vec3 hash33(vec3 p)
     {
         p = fract(p * vec3(443.8975,397.2973, 491.1871));
         p += dot(p.zxy, p.yxz+19.27);
         return fract(vec3(p.x * p.y, p.z*p.x, p.y*p.z));
     }

     //Very happy with this star function, cheap and smooth
     vec3 stars(in vec3 p)
     {
         // 47fps

         vec3 c = vec3(color1.rgb);
         // vec3 c = vec3(0.0);
         float res = acScreenSize.x*1.5; // too small  and they will flicker

         // more stars?
     	for (float i=0.0;i<2.0;i++)
         {
             vec3 q = fract(p*(0.15*res))-0.5;
             vec3 id = floor(p*(0.15*res));
             vec2 rn = hash33(id).xy;
             float c2 = 1.0-smoothstep(0.0, XXB,length(q));
             // float c2 = 1.0-smoothstep(0.0,0.6,length(q));
             c2 *= step(rn.x,0.0005+i*i*XXA);
             // c2 *= step(rn.x,0.0005+i*i*0.001);
             c += c2*(mix(vec3(color2.rgb),vec3(color3.rgb),rn.y)*0.25+0.75);
             // c += c2*(mix(vec3(1.0,0.49,0.1),vec3(0.75,0.9,1.0),rn.y)*0.25+0.75);
             p *= 1.4;
         }
         return c*c*.7;
     }

     vec3 startrails(in vec3 rd)
     {
         float EVO = autop? PROGRESS + (acTime * 0.5) : PROGRESS;
         vec3 col0 = stars( normalize(rotx(rd, EVO * 0.1)));
         vec3 col = col0;

         for (int i = -int(ITER); i < 0; i++)
         {
         	vec3 col1 = stars( normalize(rotx(rd, EVO * 0.1 + (float(i) * (1./600.0) ))));

         	col += col1;    
         }

         return col;
     }
 //////////////////////////
     void main() {
     if( acPass == 0 ) { gl_FragColor = texture2DCv(inputImg.texture, acScreenNorm.st); } else if( acPass==1 ) {
     vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
     vec4 texColorX = vec4(0.0,0.0,0.0,1.0) * texColor.a;

     vec2 image_size = getTexSize(inputImg.size);
     vec2 iResolution = vec2(acScreenSize.x, acScreenSize.y);
     vec2 iMouse = vec2(0.5, 0.5);

     vec2 TanRyu;
     TanRyu = ((vec2(acScreenNorm.x,1.0-acScreenNorm.y)*acScreenSize)-acLayerCenter)/acLayerSize;
     TanRyu.y*=acLayerSize.y/acLayerSize.x;
     TanRyu /= scale;
     TanRyu *= rot2m((0.0+angle)*0.0174533);
     TanRyu += vec2((0.0+position.x), (0.0-position.y))*vec2(-1.0,1.0)/500.0;
     vec2 scaleVec;
     scaleVec = vec2(scale*stretch.x,scale*stretch.y);
     TanRyu /= scaleVec;

     /////////////////////////

 	vec4 fragColor;

     	vec2 q = TanRyu;
             vec2 p = q;
     	p.x*=iResolution.x/iResolution.y;
     	vec2 mo = q;

         vec3 ro = vec3(650.0, sin(0.0*0.2)*0.25+10.0,0.0);
         vec3 eye = normalize(vec3(cos(mo.x),-0.0+mo.y,sin(mo.x)));
         vec3 right = normalize(vec3(cos(mo.x+1.5708),0.0,sin(mo.x+1.5708)));
         vec3 up = normalize(cross(right, eye));

         vec3 rd = normalize((p.x*right + p.y*up)*1.00 + eye);

         vec3 col = startrails( rd);

     	fragColor = vec4(col, color1.a);

 	    // const vec3 luminanceWeighting = vec3(0.2126, 0.7152, 0.0722);
         // vec4 gradmap;
         // float luminance = dot(fragColor.rgb, luminanceWeighting);
         // gradmap = mix(color1,color2,luminance)*fragColor.a;
 	    vec4 factor = mix(texColorX,fragColor,1.0);
 	    // vec4 factor = mix(texColorX,gradmap,1.0);

     vec4 resultfinal;
       if( blendMode==0 ) {
         resultfinal = (factor * hardness) * texColor.a; }
         // resultfinal = (newLayer(texColor, factor) * hardness) * texColor.a; }
       else if( blendMode==1 ) { factor *= hardness;
         vec4 c = factor + vec4(1.0)*(1.0-factor.a);
         resultfinal = vec4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a; }
         // resultfinal = min(factor, texColor) * texColor.a; }
       else if( blendMode==2 ) { factor *= hardness; 
         resultfinal = vec4( 1.0-((1.0-(texColor.rgb/texColor.a))*(1.0-factor.rgb)),1.0) * texColor.a; }
         // resultfinal = max(factor, texColor) * texColor.a; }

 	gl_FragColor = mix(texColor, resultfinal, alpha) * texColor.a;
       }
     }
